+interface ComplianceDetailProps {
+  checklistId: string;
+  projectId: string;
+  open: boolean;
+  onOpenChange: (open: boolean) => void;
+}
+
+function ProgressBar({ percent }: { percent: number }) {
+  const color = percent >= 100 ? "bg-green-500" : percent >= 50 ? "bg-yellow-500" : "bg-red-500";
+  return (
+    <div className="w-full bg-gray-200 rounded-full h-2">
+      <div className={`h-2 rounded-full ${color}`} style={{ width: `${percent}%` }} />
+    </div>
+  );
+}
+
+export function ComplianceDetail({ checklistId, projectId, open, onOpenChange }: ComplianceDetailProps) {
+  const { data: checklist, isLoading } = useComplianceChecklist(checklistId);
+  const { data: documentsData } = useDocuments(projectId);
+  const updateMutation = useUpdateChecklistItem();
+
+  const documents = documentsData?.items ?? [];
+  const mandatoryCount = checklist?.items?.filter((i) => i.is_mandatory).length ?? 0;
+  const completedMandatoryCount = checklist?.items?.filter((i) => i.is_mandatory && i.is_completed).length ?? 0;
+
+  if (isLoading) {
+    return (
+      <Dialog open={open} onOpenChange={onOpenChange}>
+        <DialogContent className="max-w-4xl">
+          <div className="text-center py-8">Loading...</div>
+        </DialogContent>
+      </Dialog>
+    );
+  }
+
+  if (!checklist) {
+    return (
+      <Dialog open={open} onOpenChange={onOpenChange}>
+        <DialogContent className="max-w-4xl">
+          <div className="text-center py-8 text-muted-foreground">Checklist not found</div>
+        </DialogContent>
+      </Dialog>
+    );
+  }
+
+  return (
+    <Dialog open={open} onOpenChange={onOpenChange}>
+      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
+        <DialogHeader>
+          <DialogTitle className="flex items-center gap-2">
+            {checklist.template_name ?? "Checklist"}
+            {checklist.template_standard_code && (
+              <Badge variant="outline">{checklist.template_standard_code}</Badge>
+            )}
+          </DialogTitle>
+        </DialogHeader>
