+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import {
+  Table,
+  TableBody,
+  TableCell,
+  TableHead,
+  TableHeader,
+  TableRow,
+} from "@/components/ui/table";
+import type { RFQ } from "@/types/api";
+
+interface RFQComparisonProps {
+  rfq: RFQ;
+}
+
+export function RFQComparison({ rfq }: RFQComparisonProps) {
+  if (!rfq.items || rfq.items.length === 0 || !rfq.responses || rfq.responses.length === 0) {
+    return (
+      <Card>
+        <CardContent className="pt-6">
+          <p className="text-center text-muted-foreground">No responses to compare</p>
+        </CardContent>
+      </Card>
+    );
+  }
+
+  const submittedResponses = rfq.responses.filter((r) => r.status === "submitted" || r.status === "selected");
+
+  if (submittedResponses.length < 2) {
+    return (
+      <Card>
+        <CardContent className="pt-6">
+          <p className="text-center text-muted-foreground">Need at least 2 vendor responses to compare</p>
+        </CardContent>
+      </Card>
+    );
+  }
+
+  return (
+    <Card>
+      <CardHeader>
+        <CardTitle>Vendor Comparison</CardTitle>
+      </CardHeader>
+      <CardContent>
+        <Table>
+          <TableHeader>
+            <TableRow>
+              <TableHead className="w-1/4">Item</TableHead>
+              {submittedResponses.map((response) => (
+                <TableHead key={response.id} className="text-center">
+                  {response.vendor_name || response.vendor_id.slice(0, 8)}
+                  {response.status === "selected" && (
+                    <span className="ml-1 text-xs text-green-600 font-normal">(Selected)</span>
+                  )}
+                </TableHead>
+              ))}
+            </TableRow>
+          </TableHeader>
+          <TableBody>
+            {rfq.items.map((item) => {
+              const prices = submittedResponses.map((r) => ({
+                response: r,
+                total: r.total_price ?? r.unit_price ? (r.unit_price ?? 0) * Number(item.quantity) : null,
+              }));
+
+              const validTotals = prices
+                .map((p) => p.total)
+                .filter((t): t is number => t !== null && t > 0);
+              const lowestPrice = validTotals.length > 0 ? Math.min(...validTotals) : null;
+
+              return (
+                <TableRow key={item.id}>
+                  <TableCell>
+                    <div>
+                      <p className="font-medium">{item.description}</p>
+                      <p className="text-xs text-muted-foreground">
+                        Qty: {item.quantity} {item.unit}
+                        {item.target_rate && ` | Target: ₹${item.target_rate}`}
+                      </p>
+                    </div>
+                  </TableCell>
+                  {prices.map((priceInfo) => {
+                    const isLowest = priceInfo.total === lowestPrice && lowestPrice !== null;
+                    return (
+                      <TableCell
+                        key={priceInfo.response.id}
+                        className={`text-center ${isLowest ? "bg-green-50" : ""}`}
+                      >
+                        <div>
+                          {priceInfo.response.unit_price !== null ? (
+                            <>
+                              <p className={`font-medium ${isLowest ? "text-green-700" : ""}`}>
+                                ₹{priceInfo.response.unit_price.toLocaleString()}
+                              </p>
+                              {priceInfo.total !== null && (
+                                <p className="text-xs text-muted-foreground">
+                                  Total: ₹{priceInfo.total.toLocaleString()}
+                                </p>
+                              )}
+                            </>
+                          ) : (
+                            <span className="text-muted-foreground">—</span>
+                          )}
+                        </div>
+                      </TableCell>
+                    );
+                  })}
+                </TableRow>
+              );
+            })}
+
+            <TableRow className="font-bold bg-slate-50">
+              <TableCell>Grand Total</TableCell>
+              {submittedResponses.map((response) => {
+                const grandTotal = rfq.items!.reduce((sum, item) => {
+                  const rate = response.unit_price ?? 0;
+                  return sum + rate * Number(item.quantity);
+                }, 0);
+                const isLowest = submittedResponses.every((otherResponse) => {
+                  if (otherResponse.id === response.id) return true;
+                  const otherTotal = rfq.items!.reduce((sum, item) => {
+                    const resp = submittedResponses.find((r) => r.id === otherResponse.id);
+                    return sum + (resp?.unit_price ?? 0) * Number(item.quantity);
+                  }, 0);
+                  return grandTotal <= otherTotal;
+                });
+                return (
+                  <TableCell key={response.id} className={`text-center ${isLowest ? "bg-green-100" : ""}`}>
+                    ₹{grandTotal.toLocaleString()}
+                  </TableCell>
+                );
+              })}
+            </TableRow>
+          </TableBody>
+        </Table>
+      </CardContent>
+    </Card>
+  );
+}
