import { useState } from "react";
import { useDocuments, useDeleteDocument, useDownloadDocument } from "@/hooks/useDocuments";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { DocumentUpload } from "./DocumentUpload";
import { DocumentVersions } from "./DocumentVersions";
import { ArrowLeft, ArrowRight, Download, Trash2, History } from "lucide-react";

interface DocumentListProps {
  projectId: string;
}

const CATEGORY_ORDER = [
  "Drawing",
  "Specification",
  "Approval",
  "Photo",
  "Test Report",
  "Contract",
  "Other",
];

function formatBytes(bytes: number | null | undefined): string {
  if (!bytes) return "—";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatDate(dateStr: string | null | undefined): string {
  if (!dateStr) return "—";
  return new Date(dateStr).toLocaleDateString();
}

export function DocumentList({ projectId }: DocumentListProps) {
  const [selectedCategory, setSelectedCategory] = useState<string | undefined>(undefined);
  const [page, setPage] = useState(1);
  const [versionsDocId, setVersionsDocId] = useState<string | null>(null);
  const pageSize = 10;

  const { data, isLoading } = useDocuments(projectId, selectedCategory, page, pageSize);
  const deleteMutation = useDeleteDocument();
  const downloadMutation = useDownloadDocument();

  const documents = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  const grouped = CATEGORY_ORDER.reduce<Record<string, typeof documents>>((acc, cat) => {
    acc[cat] = documents.filter((d) => d.category === cat);
    return acc;
  }, {} as Record<string, typeof documents>);

  const categoriesWithDocs = CATEGORY_ORDER.filter((cat) => grouped[cat].length > 0);

  return (
    <div className="space-y-6">
      <DocumentUpload projectId={projectId} />

      <Card>
        <CardHeader>
          <CardTitle>Documents</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex gap-2 flex-wrap">
            <Button
              variant={selectedCategory === undefined ? "default" : "outline"}
              size="sm"
              onClick={() => { setSelectedCategory(undefined); setPage(1); }}
            >
              All
            </Button>
            {CATEGORY_ORDER.map((cat) => (
              <Button
                key={cat}
                variant={selectedCategory === cat ? "default" : "outline"}
                size="sm"
                onClick={() => { setSelectedCategory(cat); setPage(1); }}
              >
                {cat}
              </Button>
            ))}
          </div>

          {isLoading ? (
            <div className="text-center py-8 text-muted-foreground">Loading...</div>
          ) : categoriesWithDocs.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No documents uploaded yet. Use the form above to upload.
            </div>
          ) : (
            categoriesWithDocs.map((category) => (
              <div key={category}>
                <h3 className="text-sm font-semibold text-muted-foreground mb-2">{category}</h3>
                <div className="rounded-md border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Name</TableHead>
                        <TableHead>Version</TableHead>
                        <TableHead>Size</TableHead>
                        <TableHead>Uploaded</TableHead>
                        <TableHead>Actions</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {grouped[category].map((doc) => (
                        <TableRow key={doc.id}>
                          <TableCell className="font-medium">{doc.original_name}</TableCell>
                          <TableCell>
                            <Badge variant="outline">v{doc.version}</Badge>
                          </TableCell>
                          <TableCell>{formatBytes(doc.size_bytes)}</TableCell>
                          <TableCell>{formatDate(doc.uploaded_at)}</TableCell>
                          <TableCell>
                            <div className="flex gap-2">
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={() =>
                                  downloadMutation.mutate({
                                    documentId: doc.id,
                                    filename: doc.original_name,
                                  })
                                }
                                title="Download"
                              >
                                <Download className="h-4 w-4" />
                              </Button>
                              {doc.version > 1 && (
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => setVersionsDocId(doc.id)}
                                  title="Version history"
                                >
                                  <History className="h-4 w-4" />
                                </Button>
                              )}
                              <Button
                                variant="ghost"
                                size="icon"
                                onClick={async () => {
                                  if (confirm("Delete this document?")) {
                                    await deleteMutation.mutateAsync({
                                      projectId,
                                      documentId: doc.id,
                                    });
                                  }
                                }}
                                title="Delete"
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            ))
          )}

          {totalPages > 1 && (
            <div className="flex items-center justify-between mt-4">
              <span className="text-sm text-muted-foreground">{total} document(s)</span>
              <div className="flex items-center gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page === 1}
                >
                  <ArrowLeft className="h-4 w-4" />
                </Button>
                <span className="text-sm">Page {page} of {totalPages}</span>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  disabled={page >= totalPages}
                >
                  <ArrowRight className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {versionsDocId && (
        <DocumentVersions
          documentId={versionsDocId}
          open={!!versionsDocId}
          onOpenChange={(open) => !open && setVersionsDocId(null)}
        />
      )}
    </div>
  );
}

