} from "@/components/ui/select";

interface DocumentUploadProps {
  projectId: string;
}

const CATEGORIES = [
  { value: "Drawing", label: "Drawing" },
  { value: "Specification", label: "Specification" },
  { value: "Approval", label: "Approval" },
  { value: "Photo", label: "Photo" },
  { value: "Test Report", label: "Test Report" },
  { value: "Contract", label: "Contract" },
  { value: "Other", label: "Other" },
];

export function DocumentUpload({ projectId }: DocumentUploadProps) {
  const [file, setFile] = useState<File | null>(null);
  const [category, setCategory] = useState<string>("Other");
  const uploadMutation = useUploadDocument();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;
    await uploadMutation.mutateAsync({ projectId, file, category });
    setFile(null);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Upload Document</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="flex items-end gap-4">
          <div className="space-y-2 flex-1">
            <Label htmlFor="doc-file">File</Label>
            <Input
              id="doc-file"
              type="file"
              accept=".pdf,.dwg,.docx,.xlsx,.jpg,.jpeg,.png,.zip"
              onChange={(e) => setFile(e.target.files?.[0] ?? null)}
            />
          </div>
          <div className="space-y-2 w-40">
            <Label htmlFor="doc-category">Category</Label>
            <Select value={category} onValueChange={setCategory}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {CATEGORIES.map((cat) => (
                  <SelectItem key={cat.value} value={cat.value}>
                    {cat.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <Button type="submit" disabled={!file || uploadMutation.isPending}>
            {uploadMutation.isPending ? "Uploading..." : "Upload"}
          </Button>
        </form>
        {uploadMutation.isError && (
          <p className="text-sm text-red-500 mt-2">Upload failed. File may exceed 50MB or have invalid type.</p>
        )}
      </CardContent>
    </Card>
  );
}

