import { Plus } from "lucide-react";

interface ComplianceListProps {
  projectId: string;
}

function ProgressBar({ percent }: { percent: number }) {
  const color = percent >= 100 ? "bg-green-500" : percent >= 50 ? "bg-yellow-500" : "bg-red-500";
  return (
    <div className="w-full bg-gray-200 rounded-full h-2">
      <div className={`h-2 rounded-full ${color}`} style={{ width: `${percent}%` }} />
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, { label: string; className: string }> = {
    not_started: { label: "Not Started", className: "bg-gray-100 text-gray-800" },
    in_progress: { label: "In Progress", className: "bg-yellow-100 text-yellow-800" },
    completed: { label: "Completed", className: "bg-green-100 text-green-800" },
  };
  const { label, className } = map[status] ?? { label: status, className: "bg-gray-100" };
  return <span className={`px-2 py-1 rounded text-xs font-semibold ${className}`}>{label}</span>;
}

export function ComplianceList({ projectId }: ComplianceListProps) {
  const [selectedChecklistId, setSelectedChecklistId] = useState<string | null>(null);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [showDetail, setShowDetail] = useState(false);

  const { data: templatesData } = useComplianceTemplates();
  const { data: checklistsData, isLoading } = useComplianceChecklists(projectId);
  const instantiateMutation = useInstantiateChecklist();

  const templates = templatesData?.items ?? [];
  const checklists = checklistsData?.items ?? [];

  const handleInstantiate = async () => {
    if (!selectedTemplateId) return;
    await instantiateMutation.mutateAsync({ projectId, templateId: selectedTemplateId });
    setSelectedTemplateId(null);
  };

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center justify-between">
            <span>Compliance Checklists</span>
            <div className="flex items-center gap-2">
              <Select value={selectedTemplateId ?? ""} onValueChange={(v) => setSelectedTemplateId(v)}>
                <SelectTrigger className="w-64">
                  <SelectValue placeholder="Select a template..." />
                </SelectTrigger>
                <SelectContent>
                  {templates.map((t) => (
                    <SelectItem key={t.id} value={t.id}>
                      {t.name} ({t.standard_code})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button
                size="sm"
                onClick={handleInstantiate}
                disabled={!selectedTemplateId || instantiateMutation.isPending}
              >
                <Plus className="h-4 w-4 mr-1" />
                {instantiateMutation.isPending ? "Creating..." : "Instantiate"}
              </Button>
            </div>
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {isLoading ? (
            <div className="text-center py-8 text-muted-foreground">Loading...</div>
          ) : checklists.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No compliance checklists. Select a template above to create one.
            </div>
          ) : (
            <div className="grid gap-4 md:grid-cols-2">
              {checklists.map((checklist) => (
                <Card
                  key={checklist.id}
                  className="cursor-pointer hover:bg-muted/50"
                  onClick={() => {
                    setSelectedChecklistId(checklist.id);
                    setShowDetail(true);
                  }}
                >
                  <CardHeader className="pb-2">
                    <CardTitle className="text-base flex items-center justify-between">
                      <span>{checklist.template_name ?? "Checklist"}</span>
                      <StatusBadge status={checklist.status} />
                    </CardTitle>
                    {checklist.template_standard_code && (
                      <p className="text-sm text-muted-foreground">{checklist.template_standard_code}</p>
                    )}
                  </CardHeader>
                  <CardContent className="space-y-2">
                    <div className="flex justify-between text-sm">
                      <span>{checklist.items?.length ?? 0} items</span>
                      <span>{checklist.progress_percent.toFixed(0)}%</span>
                    </div>
                    <ProgressBar percent={checklist.progress_percent} />
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {showDetail && selectedChecklistId && (
        <ComplianceDetail
          checklistId={selectedChecklistId}
          projectId={projectId}
          open={showDetail}
          onOpenChange={(open) => {
            setShowDetail(open);
            if (!open) setSelectedChecklistId(null);
          }}
        />
      )}
    </div>
  );
}

import { useComplianceChecklist, useUpdateChecklistItem, useDocuments } from "@/hooks/useCompliance";
import { ChecklistItemRow } from "./ChecklistItemRow";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

interface ComplianceDetailProps {
  checklistId: string;
  projectId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function ProgressBar({ percent }: { percent: number }) {
  const color = percent >= 100 ? "bg-green-500" : percent >= 50 ? "bg-yellow-500" : "bg-red-500";
  return (
    <div className="w-full bg-gray-200 rounded-full h-2">
      <div className={`h-2 rounded-full ${color}`} style={{ width: `${percent}%` }} />
    </div>
  );
}

export function ComplianceDetail({ checklistId, projectId, open, onOpenChange }: ComplianceDetailProps) {
  const { data: checklist, isLoading } = useComplianceChecklist(checklistId);
  const { data: documentsData } = useDocuments(projectId);
  const updateMutation = useUpdateChecklistItem();

  const documents = documentsData?.items ?? [];
  const mandatoryCount = checklist?.items?.filter((i) => i.is_mandatory).length ?? 0;
  const completedMandatoryCount = checklist?.items?.filter((i) => i.is_mandatory && i.is_completed).length ?? 0;

  if (isLoading) {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-4xl">
          <div className="text-center py-8">Loading...</div>
        </DialogContent>
      </Dialog>
    );
  }

  if (!checklist) {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-4xl">
          <div className="text-center py-8 text-muted-foreground">Checklist not found</div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {checklist.template_name ?? "Checklist"}
            {checklist.template_standard_code && (
              <Badge variant="outline">{checklist.template_standard_code}</Badge>
            )}
          </DialogTitle>
        </DialogHeader>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium">Progress</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <div className="flex justify-between text-sm">
              <span>
                {checklist.items?.filter((i) => i.is_completed).length ?? 0} / {checklist.items?.length ?? 0} items
                {mandatoryCount > 0 && ` (${completedMandatoryCount}/${mandatoryCount} mandatory)`}
              </span>
              <span>{checklist.progress_percent.toFixed(0)}%</span>
            </div>
            <ProgressBar percent={checklist.progress_percent} />
          </CardContent>
        </Card>

        <div className="space-y-2">
          <h3 className="text-sm font-semibold">Checklist Items</h3>
          {checklist.items?.map((item) => (
            <ChecklistItemRow
              key={item.id}
              item={item}
              documents={documents}
              onToggle={async (isCompleted, evidenceDocumentId) => {
                await updateMutation.mutateAsync({
                  checklistId,
                  itemId: item.id,
                  isCompleted,
                  evidenceDocumentId,
                });
              }}
            />
          ))}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import type { ChecklistItem, Document } from "@/types/api";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

interface ChecklistItemRowProps {
  item: ChecklistItem;
  documents: Document[];
  onToggle: (isCompleted: boolean, evidenceDocumentId?: string) => Promise<void>;
}

export function ChecklistItemRow({ item, documents, onToggle }: ChecklistItemRowProps) {
  const [evidenceId, setEvidenceId] = useState<string | undefined>(
    item.evidence_document_id ?? undefined
  );
  const [isUpdating, setIsUpdating] = useState(false);

  const handleToggle = async (checked: boolean) => {
    setIsUpdating(true);
    try {
      await onToggle(checked, evidenceId);
    } finally {
      setIsUpdating(false);
    }
  };

  return (
    <div className={`flex items-start gap-3 p-3 rounded border ${item.is_mandatory ? "bg-red-50 border-red-200" : "bg-white"}`}>
      <input
        type="checkbox"
        checked={item.is_completed}
        onChange={(e) => handleToggle(e.target.checked)}
        disabled={isUpdating}
        className="mt-1 h-4 w-4 rounded border-gray-300"
      />
      <div className="flex-1 space-y-1">
        <div className="flex items-center gap-2">
          <span className={item.is_completed ? "line-through text-muted-foreground" : ""}>
            {item.description}
          </span>
          {item.is_mandatory && <Badge variant="destructive">Mandatory</Badge>}
          {item.category && <Badge variant="outline">{item.category}</Badge>}
        </div>
        {item.is_completed && item.completed_at && (
          <p className="text-xs text-muted-foreground">
            Completed on {new Date(item.completed_at).toLocaleDateString()}
          </p>
        )}
      </div>
      <div className="w-48">
        <Select
          value={evidenceId ?? ""}
          onValueChange={(v) => {
            setEvidenceId(v || undefined);
            if (item.is_completed) {
              handleToggle(true);
            }
          }}
        >
          <SelectTrigger>
            <SelectValue placeholder="Link evidence..." />
          </SelectTrigger>
          <SelectContent>
            {documents.map((doc) => (
              <SelectItem key={doc.id} value={doc.id}>
                {doc.original_name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    </div>
  );
}

